                                title: "Bort platformasi asosi",
                                value: "Ochiq profillardan tayyorlangan payvandlangan ramali konstruksiya. Bo‘ylama lonjeronlar va ko‘ndalang balkalar, HOSSEN profilidan tayyorlangan bort va old devordan iborat. Platformaning ramka profilidagi yukni mahkamlash uchun galvanizlangan ilgaklar (yuklash kengligini kamaytirmaydi), har ikki tomonda 7 tadan.",
