                                value: "Alyuminiy yoki galvanizatsiyalangan po‘latdan tayyorlangan bukiladigan bortlar. Har bir tomonda 2 ta seksiyadan, balandligi 400 mm. Bortlarni ochish burchagi – 180°. Har bir tomonda alyuminiy qulflarga ega 2 ta tez yechiladigan ustun.",
