                                title: "Karkas",
                                value: "Po‘latdan tayyorlangan, balandligi 2850 mm. Roliklar ustidagi alyuminiy yo‘naltirgichlarga ega tentni alohida surish mexanizmi: tom va yon tomonlar. Tomni surish uchun ilgak-qarmoq, karkasning o‘ng orqa ustuniga mahkamlash kronshteyni bilan. Uch qator taxtadan yasalgan panjara. Darvozalar ustidagi olinadigan tom ko‘ndalang balkasi balandlik bo‘yicha cheklovlarsiz yuklash imkonini beradi. Orqa darvozalar ustida suvni chiqaruvchi alyuminiy soyabon. Orqa va old ustunlar galvanizatsiyalangan.",
