        // /////////////////////////////PRODUCTION PAGE INFO/////////////////////////////////
        productionPage: {
            pageTitle: "Ishlab chiqarish",

            text1: "«RusTrak» kompaniyasi — Nijniy Novgorod shahrida tijorat transporti va maxsus texnika ishlab chiqaruvchi yetakchi korxona. Mahsulotlarimiz qatoriga avtofurgonlar, bortli platformalar, kran-manipulyatorlar, ustaxonalar, oziq-ovqat sisternalari, avtotoplivazapravshiklar, avtogidropodyomniklar, samosvallar, vakuum mashinalari, evakuatorlar va ilgakli yuklagichlar kiradi. Barcha avtomobillar o‘z ishlab chiqarish korxonamizda yig‘iladi.",

            text2: "«RusTrak» ishlab chiqarish quvvatlari umumiy maydoni 7000 kvadrat metrdan ortiq bo‘lgan 3 ta korpusdan iborat. Stanoklar parki zamonaviy yuqori texnologiyali uskunalar bilan jihozlangan bo‘lib, bu tayyor mahsulotlarning yuqori sifatini ta’minlaydi. Kompaniya dunyoga mashhur va mahalliy ishlab chiqaruvchilarning butlovchi qismlaridan foydalanadi. Bugungi kunda kompaniyaning ishlab chiqarish quvvati oyiga 110 donagacha texnikani tashkil etadi.",

            title1: "Yuqori malakali xodimlar",

            text3: "«RusTrak» MChJ mahsulotlarining sifati kompaniyaning zamonaviy texnologik uskunalarida ishlaydigan professionallar jamoasiga bog‘liq. Kompaniya rahbariyati xodimlariga g‘amxo‘rlik qilib, maksimal darajada qulay mehnat sharoitlarini yaratadi va ularning kasbiy tayyorgarligini oshiradi. Har olti oyda kompaniya xodimlari bilim va ko‘nikmalarini qayta attestatsiyadan o‘tkazadi hamda malaka oshirish kurslarida qatnashadi.",

            title2: "O‘z konstruktorlik byurosi",

            text4: "«RusTrak» kompaniyasining o‘z konstruktorlik va texnologik byurosi mavjud bo‘lib, u ishlab chiqarish bo‘limi bilan yaqindan hamkorlik qiladi. Bunday ish tizimi mijozlarimizning istaklarini hisobga olgan holda ishlab chiqarilayotgan maxsus texnikani doimiy ravishda takomillashtirish va modernizatsiya qilish imkonini beradi. Biz deyarli har qanday ehtiyoj uchun avtomobil ishlab chiqarishga tayyormiz!",

            title3: "Sifat nazorati",

            text5: "Mahsulotlarimiz sifat nazorati ishlab chiqarishning barcha bosqichlarida amalga oshiriladi. Biz faqat ishonchli butlovchi qismlardan foydalanamiz va ularni tekshirilgan yetkazib beruvchilardan xarid qilamiz. «RusTrak» mutaxassislari ishlab chiqarish texnologiyasiga rioya qilinishini qat’iy nazorat qiladi. Ishlab chiqarilayotgan mahsulotlarni doimiy test va sinovlardan o‘tkazish shikoyatlar kelib tushishining oldini oladi. Korxonada mahsulot muvofiqligini sertifikatlashning xalqaro amaliyoti joriy etilgan: ishlab chiqarishimizdan chiqadigan har bir maxsus texnika birligi xalqaro namunadagi sertifikatga (ISO 9001) ega.",

            text6: "Sifat nazorati bo‘limi har bir texnika birligini baholaydi, bu esa xaridorlarimizga texnikaning uzoq muddat xizmat qilishini va ishonchli ishlashini kafolatlaydi.",
        },
