        // /////////////////////////////KREDIT I LIZING PAGE INFO/////////////////////////////////
        kreditPage: {
            pageTitle:
                "RusTrak kompaniyasining avto-maxsus texnikasi uchun kredit va lizing",

            text: "RusTrak kompaniyasi avto-maxsus texnikani kredit va lizing asosida xarid qilish imkoniyatini taqdim etadi. Biz barcha banklar va lizing kompaniyalari bilan ishlaymiz. Eslab qoling, siz o‘zingizga mos keladigan istalgan lizing kompaniyasini tanlashingiz mumkin.",

            title1: "Lizingning asosiy shartlari",

            text1: "Boshlang‘ich to‘lov texnika qiymatining 5–30 foizini tashkil etadi. Lizing obyektining yillik qimmatlashuvi 8–9%. Lizing to‘lovlarini amalga oshirish muddati 6 oydan 5 yilgacha. Lizing bo‘yicha to‘liq hisob-kitob amalga oshirilgandan so‘ng texnika kompaniyangiz mulkiga o‘tadi.",

            title2: "Lizing sxemalarining afzalliklari:",

            text2: "To‘lovni maksimal darajada kechiktirish imkoniyati. Tezlashtirilgan amortizatsiya: lizing bitimi ishtirokchilari lizing predmetining tezlashtirilgan amortizatsiyasi mexanizmini 3 gacha bo‘lgan tezlashtirish koeffitsiyenti bilan qo‘llash huquqiga ega. Bu texnikaning xarajatini tezroq qoplash va lizing shartnomasi muddatini o‘zgartirish imkonini beradi. Soliqni optimallashtirish: lizing shartnomasi bo‘yicha amalga oshiriladigan barcha to‘lovlar mahsulot tannarxiga kiritiladi va shu orqali foyda solig‘i bo‘yicha soliqqa tortiladigan bazani kamaytiradi. Lizing oluvchining mablag‘larini tejash: ko‘p hollarda lizing predmeti lizing kompaniyasining balansida bo‘lgani sababli mol-mulk solig‘ini to‘lash zarurati mavjud emas. Korxonaning o‘z mablag‘larini bir vaqtning o‘zida va to‘liq hajmda sarflamasdan mulkni xarid qilish va undan foydalanish imkoniyati. Lizing shartnomasi muddati tugagach, soliq yukidan to‘liq ozod qilingan lizing predmetini mulk sifatida xarid qilish imkoniyati. Lizing oluvchi tomonidan lizing predmetini va uning sotuvchisini mustaqil tanlash imkoniyati.",

            title3: "Lizingning uchta asosiy turi:",

            titleInfo: [
                {
                    title: "Moliyaviy lizing",

                    text: "Lizing beruvchi (lizing kompaniyasi) lizing oluvchi tomonidan ko‘rsatilgan mulkni belgilangan sotuvchidan o‘z mulki sifatida sotib oladi va ushbu mulkni lizing predmeti sifatida belgilangan shartlar asosida vaqtinchalik egalik qilish va foydalanish uchun lizing oluvchiga topshiradi. Mulk (lizing predmeti) lizing oluvchi barcha lizing to‘lovlarini amalga oshirgandan so‘ng uning mulkiga o‘tadi.",
                },

                {
                    title: "Operativ lizing",

                    text: "Mulk lizing oluvchi tomonidan sotib olinmaydi, balki lizing kompaniyasining mulki bo‘lib qoladi va lizing shartnomasi muddati tugagach, yana lizing yoki ijara asosida boshqa tomonga beriladi.",
                },

                {
                    title: "Qaytarma lizing",

                    text: "Korxona mulkni o‘z mablag‘lari hisobidan sotib oladi va keyin lizing kompaniyasiga murojaat qiladi. Bu aylanma mablag‘larni nisbatan tez qaytarish usullaridan biridir. Lizing kompaniyasi ushbu mulkni lizing predmeti sifatida ko‘rib chiqadi va uni korxonadan oldi-sotdi shartnomasi asosida sotib oladi. Keyin ayni shu mulk o‘sha korxonaga lizing asosida beriladi.",
                },
            ],

            title4: `Hamkor haqida ma’lumot — "CARCADE" kompaniyasi`,

            text4: "CARCADE kompaniyasi universal lizing hamkoridir. CARCADE yengil avtomobillar bilan bir qatorda tijorat transportini xarid qilishni ham moliyalashtiradi. Tijorat avtomobillari yoki maxsus texnikani moliyaviy hisobot taqdim etmasdan, 2 ta hujjat asosida lizingga rasmiylashtirish mumkin. Bitimni rasmiylashtirish shartlari: boshlang‘ich to‘lov 4% dan 50% gacha, lizing muddati 12 oydan 60 oygacha, oxirgi to‘lov 1% dan 15% gacha. CARCADE mijozlari uchun qo‘shimcha afzalliklar: bo‘lib-bo‘lib to‘lanadigan KASKO, bepul sessiya, elektron hujjat aylanishi. Maxsus texnika va uni lizing asosida xarid qilish bo‘yicha batafsil ma’lumot olish uchun quyidagi telefon raqamiga murojaat qiling:",

            telefon: "8 (831) 225-00-55",
        },
